import { Base2, View2 as LocalView } from "./chunk.js";
import { Parser2 as InputParser } from "./chunk.js";
export { Base2 as Base, LocalView as View };
export { Metrics2 as Metrics } from "./chunk.js";

export class Input {
  parser = null;
  constructor() { this.parser = new InputParser(); }
  push(value) { this.parser?.push(value); }
  read() { return this.parser ? this.parser.describe() : "absent"; }
  save() { return this.parser; }
  clear() { this.parser?.reset(); }
  close() { this.parser = null; }
  open() { this.parser = new InputParser(); }
}

export class FactoryInput {
  parser = null;
  open(value) { this.parser = InputParser.create(value); }
  close() { this.parser = null; }
  read() { return this.parser ? this.parser.describe() : "absent"; }
  save() { return this.parser; }
}
